#!/bin/sh
# Profile-scoped harness tool for profile ${PROFILE_NAME}.
# Generated by devkit; edits are lost on `devkit profile sync`.
#
# PATH is not enough: agentctl and friends read $AGENTS_HOME, not $HOME/.agents.
# The invoked name ($0) selects $AGENTS_HOME/bin/<name> (the kit tools, not
# the full core/ skills tree).
set -eu
DEVKIT_PROFILE="${PROFILE_NAME}"
export DEVKIT_PROFILE
DEVKIT_PROFILE_HOME="${PROFILE_HARNESS_DIR}"
export DEVKIT_PROFILE_HOME
AGENTS_HOME="${PROFILE_AGENTS_HOME}"
export AGENTS_HOME
PATH="${PROFILE_BIN_DIR}:${PATH}"
export PATH
name=$(basename "$0")
exec "${PROFILE_AGENTS_HOME}/bin/${name}" "$@"
